/// <summary>
/// class <c>METTelemetryPOCreatedInfoEvent</c> is used to log error event whenever purchase order creation info event.
/// </summary>
internal final class METTelemetryPOCreatedInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOCreatedInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOCreatedInfoEvent</c> </returns>
public static METTelemetryPOCreatedInfoEvent construct()
{
    return new METTelemetryPOCreatedInfoEvent();
}

/// <summary>
/// Run confirmation journal error event
/// </summary>
/// <param name = "_purchTable"> purchase table <c>PurchTable</c> </param>
public static void runTelemetryEvent(PurchTable _purchTable)
{
    METTelemetryPOCreatedInfoEvent poCreationEvent = METTelemetryPOCreatedInfoEvent::construct();

    poCreationEvent.addRunTimePropertyToAppinsights(_purchTable);

    poCreationEvent.processEvent(METTelemetryEventNames::POCreatedEvent);
}

protected void new()
{
    super();

    this.eventId = METTelemetryEventNames::POCreatedEvent;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchTable"> table <c>_purchTable</c> </param>
public void addRunTimePropertyToAppinsights(PurchTable _purchTable)
{
    this.addRuntimeProperty('PurchaseOrderId', _purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,_purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', _purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', _purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', _purchTable.ItemBuyerGroupId);
}
